<script setup>
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue'
import * as echarts from 'echarts'
import http from '../api/http.js'
const data=ref(null),error=ref(''),days=ref(7),loading=ref(false),lineEl=ref(),pieEl=ref()
let line,pie,disposed=false
async function load(){loading.value=true;error.value='';try{const r=await http.get('/api/stats/overview',{params:{days:days.value}});if(disposed)return;data.value=r.data;await nextTick();if(disposed)return;line??=echarts.init(lineEl.value);pie??=echarts.init(pieEl.value);line.setOption({title:{text:'每日已知 Token 消耗',left:'center'},tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:65,right:25,bottom:60},xAxis:{type:'category',data:data.value.series.map(d=>d.date.slice(5))},yAxis:{type:'value'},series:[{name:'Prompt Tokens',type:'line',data:data.value.series.map(d=>d.promptTokens)},{name:'Completion Tokens',type:'line',data:data.value.series.map(d=>d.completionTokens)}]});pie.setOption({title:{text:'API 请求结果',left:'center'},tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['35%','65%'],data:[{name:'成功',value:data.value.success},{name:'失败',value:data.value.failed},{name:'用户取消',value:data.value.cancelled}]}]})}catch(e){error.value=e.message}finally{loading.value=false}}
const resize=()=>{line?.resize();pie?.resize()}
onMounted(()=>{load();window.addEventListener('resize',resize)})
onBeforeUnmount(()=>{disposed=true;window.removeEventListener('resize',resize);line?.dispose();pie?.dispose()})
</script>
<template><main class="workspace asset-workspace"><header class="topbar"><RouterLink class="brand" to="/">AI 出海营销工坊</RouterLink><nav class="asset-nav"><RouterLink to="/">资产中心</RouterLink><RouterLink to="/copy">文案工坊</RouterLink><RouterLink to="/scene">场景生图</RouterLink><RouterLink to="/stats">运营看板</RouterLink></nav></header><section class="asset-intro"><span class="eyebrow">04 / OPERATIONS</span><h1>每一次调用，都有记录。</h1><p>统计启用审计后的真实调用，取消不算失败；已知Token消耗不等于实际账单。</p></section><el-select v-model="days" style="width:140px" @change="load"><el-option v-for="n in [7,14,30]" :key="n" :value="n" :label="`最近${n}天`"/></el-select><el-button :loading="loading" @click="load">刷新统计</el-button><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="data"><el-alert v-if="data.unknownUsageCalls" :title="`${data.unknownUsageCalls}条调用未提供完整Token，用量仅汇总已知值`" type="warning" :closable="false"/><p>{{data.note}} 统计时区：{{data.timezone}}；当前不含演示数据。</p><div class="stats-grid"><el-card><el-statistic title="已知 Token 合计" :value="data.totalTokens"/></el-card><el-card><el-statistic title="API 调用次数（含取消）" :value="data.totalCalls"/></el-card><el-card><el-statistic title="成功率（排除取消）" :value="data.successRate" suffix="%"/></el-card></div><div class="charts"><el-card><div ref="lineEl" style="height:360px"/></el-card><el-card><div ref="pieEl" style="height:360px"/></el-card></div><el-card header="各功能消耗明细"><el-table :data="data.byPurpose"><el-table-column prop="_id" label="功能"/><el-table-column prop="calls" label="调用次数"/><el-table-column prop="tokens" label="已知Token"/></el-table></el-card></template><el-skeleton v-else-if="loading" :rows="8" animated/><footer>刘嘉略 · 0120251050 <span>Token审计与交付 · 实战8</span></footer></main></template>
<style scoped>.stats-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:20px 0}.charts{display:grid;grid-template-columns:1.4fr 1fr;gap:20px;margin-bottom:20px}@media(max-width:760px){.stats-grid,.charts{grid-template-columns:1fr}}</style>
